```yaml
name: Remove SLO Label

on:
  workflow_call:
    inputs:
      pr_number:
        required: true
        type: string

permissions:
  contents: read
  issues: write

jobs:
  remove-slo-label:
    if: ${{ always() }}
    runs-on: ubuntu-latest
    steps:
      - name: Remove SLO label
        uses: actions/github-script@v7
        env:
          PR_NUMBER: ${{ inputs.pr_number }}
        with:
          script: |
            const prNumber = process.env.PR_NUMBER;
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: 'SLO'
              });
              console.log(`Removed SLO label from PR #${prNumber}`);
            } catch (error) {
              if (error.status !== 404) {
                throw error;
              }
              console.log(`SLO label not found on PR #${prNumber}`);
            }
